// tcim-admin-workbench/item-label.mjs
var originalLabel = (item) => /^TCIM-C-\d{4}$/.test(item.itemId) && Number(item.itemId.slice(-4)) >= 1 && Number(item.itemId.slice(-4)) <= 10 ? "C" + item.itemId.slice(-4) : null;
var labelPrefix = (item) => item.content.itemType === "pilot" ? "P" : "C";
var formatItemLabel = (prefix2, n) => prefix2 + String(n).padStart(4, "0");
async function ensureCloudItemLabel(u, item) {
  let entry = await u.get("item_label", item.itemId);
  if (entry) return entry.code;
  let code = originalLabel(item);
  if (!code) {
    const prefix2 = labelPrefix(item), key = "item-label-next:" + prefix2, c = await u.get("control_meta", key), n = (c?.value ?? (prefix2 === "C" ? 10 : 0)) + 1;
    code = formatItemLabel(prefix2, n);
    await u.put("control_meta", key, { value: n });
  }
  await u.put("item_label", item.itemId, { code });
  return code;
}

// tcim-admin-workbench/save-receipt.mjs
function saveReceiptKey(token2, kind, actor = "local") {
  if (token2 == null || token2 === "") return null;
  if (typeof token2 !== "string" || !/^[a-zA-Z0-9-]{16,80}$/.test(token2)) throw new UserError("\u4FDD\u5B58\u8BF7\u6C42\u7F16\u53F7\u65E0\u6548\uFF0C\u8BF7\u91CD\u65B0\u6253\u5F00\u8868\u5355\u3002");
  return "save:" + hash([actor, kind, token2]);
}
function verifySaveReceipt(receipt, inputHash) {
  if (receipt && receipt.inputHash !== inputHash) throw new UserError("\u4E0A\u6B21\u63D0\u4EA4\u7684\u5185\u5BB9\u5DF2\u4FDD\u5B58\u3002\u8BF7\u5148\u5230\u5217\u8868\u67E5\u770B\uFF0C\u518D\u4ECE\u8BE6\u60C5\u4FEE\u6539\uFF0C\u907F\u514D\u91CD\u590D\u5EFA\u7ACB\u3002", 409);
}

// tcim-admin-workbench/import-receipt.mjs
var importFingerprint = (kind, payload) => hash([kind, payload]);
async function cloudImportReceipt(records, workbench, actor, token2, inputHash) {
  const key = saveReceiptKey(token2, "item", actor);
  if (!key) return null;
  const old = await records.get("save_receipt", key);
  verifySaveReceipt(old, inputHash);
  return old ? workbench.item(old.id) : null;
}

